#include "game_status.h"
#include "king_check.h"
#include "legal_move.h"

// `is_insufficient_material` was generated by GPT 5.6 Luna via VS Code Copilot
// SDK.
static bool is_insufficient_material(const ChessBoard *board) {
  unsigned int non_king_pieces = 0;
  unsigned int bishops[2] = {0, 0};
  int bishop_square_colors[2] = {-1, -1};

  for (unsigned int row = 0; row < BOARD_SIZE; row++) {
    for (unsigned int col = 0; col < BOARD_SIZE; col++) {
      Piece piece = get_piece(board, create_coords(row, col));

      if (piece.name == NONE || piece.name == KING) {
        continue;
      }

      if (piece.name == PAWN || piece.name == ROOK || piece.name == QUEEN) {
        return false;
      }

      non_king_pieces++;
      if (piece.name == BISHOP) {
        int square_color = (int)((row + col) % 2);
        bishops[piece.color]++;
        bishop_square_colors[piece.color] = square_color;
      }
    }
  }

  if (non_king_pieces <= 1) {
    return true;
  }

  return non_king_pieces == 2 && bishops[CHESS_BLACK] == 1 && bishops[CHESS_WHITE] == 1 &&
         bishop_square_colors[CHESS_BLACK] == bishop_square_colors[CHESS_WHITE];
}

static bool exceeds_50_move_rule(const ChessBoard *board) {
  return board->meta.halfmove_clock >= 100;
}

static GameStatus get_game_status_from_context(ChessBoard *board, ChessColor color,
                                               const GameContext *context) {
  if (context == NULL) {
    return GAME_IN_PROGRESS;
  }
  if (context->is_timed && context->remaining_seconds[color] == 0) {
    return GAME_LOSS_TIMEOUT;
  }
  if (is_threefold_repetition(&context->history, board, color)) {
    return GAME_DRAW_3FOLD_REPETITION;
  }
  return GAME_IN_PROGRESS;
}

GameStatus get_game_status(ChessBoard *board, ChessColor color,
                           const GameContext *context) {
  GameStatus status = get_game_status_from_context(board, color, context);
  if (status != GAME_IN_PROGRESS) {
    return status;
  }

  if (exceeds_50_move_rule(board)) {
    return GAME_DRAW_50_MOVE_RULE;
  }
  if (is_insufficient_material(board)) {
    return GAME_DRAW_INSUFFICIENT_MATERIAL;
  }

  bool king_in_check = is_king_in_check(board, color);
  bool can_not_move = !has_legal_move(board, color);

  if (can_not_move) {
    return king_in_check ? GAME_CHECKMATE : GAME_STALEMATE;
  }
  return king_in_check ? GAME_CHECK : GAME_IN_PROGRESS;
}

bool is_end_game(ChessBoard *board) {
  return board->meta.halfmove_clock >= 100 || is_insufficient_material(board) ||
         !(has_legal_move(board, CHESS_BLACK) && has_legal_move(board, CHESS_WHITE));
}